/* @lc app=leetcode id=2813 lang=kotlin */
class Solution { fun findMaximumElegance(A: Array<IntArray>, k: Int): Long = A.sortedByDescending { it[0] }.let { sorted -> sorted.take(k).let { initial -> initial.fold(Triple(0L, mutableSetOf<Int>(), mutableListOf<Int>())) { acc, item -> Triple(acc.first + item[0], acc.second.also { acc.second.add(item[1]) }, acc.third.also { if (!acc.second.add(item[1])) acc.third.add(item[0]) }) }.let { state -> sorted.drop(k).fold(state.first + state.second.size.toLong() * state.second.size to state) { (maxE, cur), item -> if (cur.third.isNotEmpty() && cur.second.add(item[1])) (cur.first - cur.third.removeAt(cur.third.size - 1) + item[0]).let { nextSum -> maxOf(maxE, nextSum + cur.second.size.toLong() * cur.second.size) to cur.copy(first = nextSum) } else maxE to cur }.first } } } }